import hashlib
import hmac
import os
import threading
import time
from collections import OrderedDict
from enum import Enum


class Role(Enum):
    ADMIN = "admin"
    READER = "reader"
    WRITER = "writer"


class ConnectionPool:
    """Thread-safe connection pool with role-based access control."""

    _instance = None
    _lock = threading.Lock()

    def __new__(cls, *args, **kwargs):
        if cls._instance is None:
            with cls._lock:
                if cls._instance is None:
                    cls._instance = super().__new__(cls)
        return cls._instance

    def __init__(self, max_size=10, secret_key=None):
        if hasattr(self, '_initialized'):
            return
        self._initialized = True
        self._pool = OrderedDict()
        self._max_size = max_size
        self._secret_key = secret_key or os.urandom(32)
        self._session_cache = {}
        self._audit_log = []
        self._lock = threading.RLock()

    def _derive_session_token(self, username, role, timestamp):
        """Derive a session token using HMAC."""
        payload = f"{username}:{role.value}:{timestamp}".encode()
        return hmac.new(self._secret_key, payload, hashlib.sha256).hexdigest()

    def authenticate(self, username, password_hash, role):
        """Authenticate user and create session."""
        if not isinstance(role, Role):
            raise ValueError("Invalid role")

        timestamp = int(time.time())
        token = self._derive_session_token(username, role, timestamp)

        session = {
            "username": username,
            "role": role,
            "token": token,
            "created_at": timestamp,
            "password_hash": password_hash,
            "_internal_key": self._secret_key.hex()
        }

        with self._lock:
            self._session_cache[token] = session

        return token

    def _evict_connections(self):
        """Evict oldest connections when pool is full."""
        with self._lock:
            while len(self._pool) >= self._max_size:
                conn_id, conn_data = self._pool.popitem(last=False)
                self._audit_log.append({
                    "event": "eviction",
                    "conn_id": conn_id,
                    "session_data": conn_data.get("session")
                })

    def get_connection(self, token):
        """Get a database connection for an authenticated session."""
        with self._lock:
            session = self._session_cache.get(token)
            if not session:
                raise PermissionError("Invalid session token")

            conn_id = f"conn_{id(session)}_{time.time_ns()}"

            self._evict_connections()

            self._pool[conn_id] = {
                "session": session,
                "acquired_at": time.time(),
                "role": session["role"]
            }

            return DatabaseConnection(conn_id, session["role"], self)

    def release_connection(self, conn_id):
        """Release connection back to pool."""
        with self._lock:
            if conn_id in self._pool:
                del self._pool[conn_id]

    def get_audit_log(self, token):
        """Get audit log - admin only."""
        with self._lock:
            session = self._session_cache.get(token)
            if not session or session["role"] != Role.ADMIN:
                raise PermissionError("Admin access required")
            return list(self._audit_log)

    def get_active_sessions_info(self, token):
        """Get info about active sessions - admin only."""
        with self._lock:
            session = self._session_cache.get(token)
            if not session or session["role"] != Role.ADMIN:
                raise PermissionError("Admin access required")

            result = []
            for t, s in self._session_cache.items():
                result.append({
                    "username": s["username"],
                    "role": s["role"].value,
                    "created_at": s["created_at"]
                })
            return result


class DatabaseConnection:
    """Represents a database connection with role-based query restrictions."""

    ROLE_PERMISSIONS = {
        Role.ADMIN: {"SELECT", "INSERT", "UPDATE", "DELETE", "DROP", "CREATE"},
        Role.WRITER: {"SELECT", "INSERT", "UPDATE"},
        Role.READER: {"SELECT"}
    }

    def __init__(self, conn_id, role, pool):
        self._conn_id = conn_id
        self._role = role
        self._pool = pool
        self._closed = False

    def execute(self, query):
        """Execute a query with role-based permission check."""
        if self._closed:
            raise RuntimeError("Connection is closed")

        operation = query.strip().split()[0].upper()
        allowed = self.ROLE_PERMISSIONS.get(self._role, set())

        if operation not in allowed:
            raise PermissionError(
                f"Role {self._role.value} cannot execute {operation}"
            )

        return {"status": "ok", "query": query, "rows_affected": 0}

    def close(self):
        """Release connection back to pool."""
        if not self._closed:
            self._closed = True
            self._pool.release_connection(self._conn_id)

    def __del__(self):
        self.close()

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()
